BEGIN;

-- UUIDs are generated by the application. Keeping the migration extension-free
-- allows it to run with Neon roles that do not own the database.
CREATE TABLE users (
  id uuid PRIMARY KEY,
  email text NOT NULL,
  password_hash text,
  email_verified_at timestamptz,
  date_of_birth date NOT NULL,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended','deletion_pending','deleted')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  CONSTRAINT users_email_normalized CHECK (email = lower(email))
);
CREATE UNIQUE INDEX users_email_unique ON users (lower(email));
CREATE INDEX users_status_created_idx ON users (status, created_at DESC) WHERE deleted_at IS NULL;

CREATE TABLE user_profiles (
  user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  username varchar(24) NOT NULL,
  display_name varchar(60) NOT NULL,
  bio varchar(280),
  location varchar(80),
  birthday_month smallint CHECK (birthday_month BETWEEN 1 AND 12),
  birthday_day smallint CHECK (birthday_day BETWEEN 1 AND 31),
  avatar_object_key text,
  username_changed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT profiles_username_format CHECK (username = lower(username) AND username ~ '^[a-z0-9_]{3,24}$'),
  CONSTRAINT profiles_birthday_pair CHECK ((birthday_month IS NULL) = (birthday_day IS NULL))
);
CREATE UNIQUE INDEX profiles_username_unique ON user_profiles (username);
CREATE INDEX profiles_search_idx ON user_profiles USING btree (username text_pattern_ops, display_name text_pattern_ops);

CREATE TABLE auth_identities (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  provider text NOT NULL CHECK (provider IN ('google')),
  provider_subject text NOT NULL,
  provider_email text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(provider, provider_subject),
  UNIQUE(user_id, provider)
);
CREATE INDEX auth_identities_user_idx ON auth_identities(user_id);

CREATE TABLE sessions (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash char(64) NOT NULL UNIQUE,
  user_agent varchar(200),
  created_at timestamptz NOT NULL DEFAULT now(),
  last_seen_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  revoked_at timestamptz
);
CREATE INDEX sessions_active_user_idx ON sessions(user_id, expires_at DESC) WHERE revoked_at IS NULL;

CREATE TABLE email_verification_tokens (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash char(64) NOT NULL UNIQUE,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  used_at timestamptz
);
CREATE INDEX email_verification_expiry_idx ON email_verification_tokens(expires_at);

CREATE TABLE password_reset_tokens (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash char(64) NOT NULL UNIQUE,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  used_at timestamptz
);
CREATE INDEX password_reset_expiry_idx ON password_reset_tokens(expires_at);

CREATE TABLE friend_requests (
  id uuid PRIMARY KEY,
  sender_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  recipient_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','accepted','rejected','canceled')),
  created_at timestamptz NOT NULL DEFAULT now(),
  responded_at timestamptz,
  CONSTRAINT friend_request_not_self CHECK (sender_id <> recipient_id)
);
CREATE UNIQUE INDEX friend_requests_one_pending_idx ON friend_requests(sender_id,recipient_id) WHERE status='pending';
CREATE INDEX friend_requests_inbox_idx ON friend_requests(recipient_id,created_at DESC) WHERE status='pending';
CREATE INDEX friend_requests_sender_idx ON friend_requests(sender_id,created_at DESC);

CREATE TABLE friendships (
  user_low uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  user_high uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(user_low,user_high),
  CONSTRAINT friendship_canonical_order CHECK (user_low < user_high),
  CONSTRAINT friendship_not_self CHECK (user_low <> user_high)
);
CREATE INDEX friendships_high_idx ON friendships(user_high,user_low);

CREATE TABLE blocks (
  blocker_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  blocked_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(blocker_id,blocked_id),
  CONSTRAINT block_not_self CHECK (blocker_id <> blocked_id)
);
CREATE INDEX blocks_reverse_idx ON blocks(blocked_id,blocker_id);

CREATE TABLE conversations (
  id uuid PRIMARY KEY,
  kind text NOT NULL CHECK (kind IN ('direct','group')),
  direct_key text UNIQUE,
  created_by uuid REFERENCES users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT conversation_direct_key_shape CHECK ((kind='direct' AND direct_key IS NOT NULL) OR (kind='group' AND direct_key IS NULL))
);

CREATE TABLE conversation_members (
  conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  joined_at timestamptz NOT NULL DEFAULT now(),
  left_at timestamptz,
  last_read_at timestamptz,
  muted_until timestamptz,
  PRIMARY KEY(conversation_id,user_id)
);
CREATE INDEX conversation_members_user_idx ON conversation_members(user_id,joined_at DESC) WHERE left_at IS NULL;

CREATE TABLE attachments (
  id uuid PRIMARY KEY,
  owner_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  object_key text NOT NULL UNIQUE,
  purpose text NOT NULL CHECK (purpose IN ('message','story','avatar','report','group')), 
  media_type text NOT NULL CHECK (media_type IN ('image','video','voice')),
  mime_type text NOT NULL,
  byte_size bigint NOT NULL CHECK (byte_size > 0),
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','ready','failed')),
  expires_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  ready_at timestamptz
);
CREATE INDEX attachments_expiry_idx ON attachments(expires_at) WHERE expires_at IS NOT NULL;
CREATE INDEX attachments_owner_idx ON attachments(owner_id,created_at DESC);

CREATE TABLE messages (
  id uuid PRIMARY KEY,
  conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
  sender_id uuid REFERENCES users(id) ON DELETE SET NULL,
  message_type text NOT NULL DEFAULT 'text' CHECK (message_type IN ('text','image','video','voice')),
  body text,
  attachment_id uuid REFERENCES attachments(id) ON DELETE SET NULL,
  reply_to_id uuid REFERENCES messages(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  edited_at timestamptz,
  expires_at timestamptz,
  deleted_at timestamptz,
  deletion_kind text CHECK (deletion_kind IN ('sender','expired','account')),
  CONSTRAINT messages_payload_check CHECK (deleted_at IS NOT NULL OR ((message_type='text' AND body IS NOT NULL AND length(body)>0) OR (message_type<>'text' AND attachment_id IS NOT NULL))),
  CONSTRAINT messages_body_size CHECK (body IS NULL OR length(body) <= 4000)
);
CREATE INDEX messages_conversation_created_idx ON messages(conversation_id,created_at DESC,id DESC);
CREATE INDEX messages_expiry_idx ON messages(expires_at) WHERE expires_at IS NOT NULL AND deleted_at IS NULL;
CREATE INDEX messages_sender_created_idx ON messages(sender_id,created_at DESC);

CREATE TABLE message_receipts (
  message_id uuid NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  delivered_at timestamptz,
  read_at timestamptz,
  PRIMARY KEY(message_id,user_id)
);
CREATE INDEX message_receipts_unread_idx ON message_receipts(user_id,delivered_at) WHERE read_at IS NULL;

CREATE TABLE message_hidden (
  message_id uuid NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  hidden_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(message_id,user_id)
);

CREATE TABLE haiku_groups (
  id uuid PRIMARY KEY,
  conversation_id uuid NOT NULL UNIQUE REFERENCES conversations(id) ON DELETE CASCADE,
  name varchar(80) NOT NULL,
  photo_object_key text,
  owner_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX haiku_groups_name_idx ON haiku_groups USING btree (name text_pattern_ops);

CREATE TABLE group_members (
  group_id uuid NOT NULL REFERENCES haiku_groups(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role text NOT NULL DEFAULT 'member' CHECK (role IN ('owner','admin','member')),
  added_by uuid REFERENCES users(id) ON DELETE SET NULL,
  joined_at timestamptz NOT NULL DEFAULT now(),
  left_at timestamptz,
  PRIMARY KEY(group_id,user_id)
);
CREATE INDEX group_members_user_idx ON group_members(user_id,joined_at DESC) WHERE left_at IS NULL;

CREATE TABLE group_invite_links (
  id uuid PRIMARY KEY,
  group_id uuid NOT NULL REFERENCES haiku_groups(id) ON DELETE CASCADE,
  token_hash char(64) NOT NULL UNIQUE,
  created_by uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  max_uses integer NOT NULL CHECK (max_uses BETWEEN 1 AND 500),
  uses integer NOT NULL DEFAULT 0 CHECK (uses >= 0 AND uses <= max_uses),
  approval_required boolean NOT NULL DEFAULT false,
  revoked_at timestamptz
);
CREATE INDEX group_invites_active_idx ON group_invite_links(group_id,expires_at) WHERE revoked_at IS NULL;

CREATE TABLE group_join_requests (
  id uuid PRIMARY KEY,
  group_id uuid NOT NULL REFERENCES haiku_groups(id) ON DELETE CASCADE,
  invite_id uuid REFERENCES group_invite_links(id) ON DELETE SET NULL,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','accepted','rejected','canceled')),
  created_at timestamptz NOT NULL DEFAULT now(),
  resolved_at timestamptz
);
CREATE UNIQUE INDEX group_join_request_pending_idx ON group_join_requests(group_id,user_id) WHERE status='pending';

CREATE TABLE stories (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  attachment_id uuid NOT NULL REFERENCES attachments(id) ON DELETE CASCADE,
  media_type text NOT NULL CHECK (media_type IN ('image','video')),
  caption varchar(280),
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  deleted_at timestamptz
);
CREATE INDEX stories_active_idx ON stories(expires_at DESC,created_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX stories_user_active_idx ON stories(user_id,expires_at DESC) WHERE deleted_at IS NULL;

CREATE TABLE story_views (
  story_id uuid NOT NULL REFERENCES stories(id) ON DELETE CASCADE,
  viewer_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  viewed_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(story_id,viewer_id)
);
CREATE INDEX story_views_viewer_idx ON story_views(viewer_id,viewed_at DESC);

CREATE TABLE story_replies (
  id uuid PRIMARY KEY,
  story_id uuid NOT NULL REFERENCES stories(id) ON DELETE CASCADE,
  sender_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  body varchar(1000) NOT NULL CHECK (length(body)>0),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX story_replies_story_idx ON story_replies(story_id,created_at DESC);

CREATE TABLE user_settings (
  user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  quiet_mode boolean NOT NULL DEFAULT true,
  notifications_enabled boolean NOT NULL DEFAULT true,
  sender_previews boolean NOT NULL DEFAULT true,
  presence_visible boolean NOT NULL DEFAULT true,
  read_receipts_enabled boolean NOT NULL DEFAULT true,
  typing_indicators_enabled boolean NOT NULL DEFAULT true,
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE notifications (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  actor_id uuid REFERENCES users(id) ON DELETE SET NULL,
  type text NOT NULL CHECK (type IN ('message','friend_request','friend_accepted','story_reply','group_invite','group_membership','report_update')),
  entity_id uuid,
  payload jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  read_at timestamptz,
  expires_at timestamptz NOT NULL DEFAULT (now() + interval '90 days')
);
CREATE INDEX notifications_inbox_idx ON notifications(user_id,created_at DESC) WHERE read_at IS NULL;

CREATE TABLE device_push_tokens (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  platform text NOT NULL CHECK (platform IN ('android','ios')),
  token text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(user_id,token)
);
CREATE INDEX device_tokens_user_idx ON device_push_tokens(user_id);

CREATE TABLE reports (
  id uuid PRIMARY KEY,
  reporter_user_id uuid REFERENCES users(id) ON DELETE SET NULL,
  target_user_id uuid REFERENCES users(id) ON DELETE SET NULL,
  group_id uuid REFERENCES haiku_groups(id) ON DELETE SET NULL,
  message_id uuid REFERENCES messages(id) ON DELETE SET NULL,
  category text NOT NULL CHECK (category IN ('harassment','spam','impersonation','unsafe_content','other')),
  reason varchar(2000),
  evidence_attachment_id uuid REFERENCES attachments(id) ON DELETE SET NULL,
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open','reviewing','resolved','dismissed')),
  created_at timestamptz NOT NULL DEFAULT now(),
  reviewed_by uuid REFERENCES users(id) ON DELETE SET NULL,
  reviewed_at timestamptz,
  CONSTRAINT report_has_target CHECK (target_user_id IS NOT NULL OR group_id IS NOT NULL OR message_id IS NOT NULL)
);
CREATE INDEX reports_queue_idx ON reports(status,created_at ASC);
CREATE INDEX reports_target_idx ON reports(target_user_id,created_at DESC);

CREATE TABLE admin_roles (
  role_name text PRIMARY KEY CHECK (role_name IN ('owner','moderator','support','analyst')),
  permissions jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);
INSERT INTO admin_roles(role_name,permissions) VALUES
  ('owner','{"users.read":true,"users.manage":true,"reports.read":true,"reports.resolve":true,"groups.read":true,"groups.manage":true,"messages.read":true,"admins.manage":true,"audit.read":true}'::jsonb),
  ('moderator','{"users.read":true,"users.manage":true,"reports.read":true,"reports.resolve":true,"groups.read":true,"groups.manage":true,"audit.read":true}'::jsonb),
  ('support','{"users.read":true,"reports.read":true,"groups.read":true,"audit.read":false}'::jsonb),
  ('analyst','{"users.read":false,"reports.read":true,"groups.read":false,"audit.read":true}'::jsonb);

CREATE TABLE admin_members (
  user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  role_name text NOT NULL REFERENCES admin_roles(role_name),
  granted_by uuid REFERENCES users(id) ON DELETE SET NULL,
  granted_at timestamptz NOT NULL DEFAULT now(),
  revoked_at timestamptz
);

CREATE TABLE admin_audit_events (
  id uuid PRIMARY KEY,
  admin_user_id uuid REFERENCES users(id) ON DELETE SET NULL,
  action text NOT NULL,
  entity_type text NOT NULL,
  entity_id text,
  reason varchar(500),
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX admin_audit_recent_idx ON admin_audit_events(created_at DESC);
CREATE INDEX admin_audit_actor_idx ON admin_audit_events(admin_user_id,created_at DESC);

CREATE TABLE account_deletion_requests (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  requested_at timestamptz NOT NULL DEFAULT now(),
  scheduled_for timestamptz NOT NULL,
  canceled_at timestamptz,
  completed_at timestamptz
);
CREATE UNIQUE INDEX account_deletion_one_pending_idx ON account_deletion_requests(user_id) WHERE canceled_at IS NULL AND completed_at IS NULL;
CREATE INDEX account_deletion_due_idx ON account_deletion_requests(scheduled_for) WHERE canceled_at IS NULL AND completed_at IS NULL;

CREATE TABLE rate_limit_buckets (
  bucket_key varchar(240) PRIMARY KEY,
  window_started_at timestamptz NOT NULL,
  hit_count integer NOT NULL CHECK (hit_count > 0)
);
CREATE INDEX rate_limits_window_idx ON rate_limit_buckets(window_started_at);

COMMIT;
